:root {
  /* Circuit Symphony Theme - holographic traces and audio-inspired pulses */
  --bg-primary: #050508;
  --bg-alt: #0b0b15;
  --text-primary: #f1f6ff;
  --text-secondary: #9fb2ff;
  --accent: #76f7ff;
  --accent-2: #ff9ed9;
  --trace: rgba(118, 247, 255, 0.28);
  --border: rgba(118, 247, 255, 0.35);
}

body {
  background: radial-gradient(circle at 15% 30%, rgba(118, 247, 255, 0.12), transparent 32%),
              radial-gradient(circle at 75% 70%, rgba(255, 158, 217, 0.14), transparent 38%),
              linear-gradient(135deg, #050508 0%, #0b0b15 58%, #050508 100%);
  color: var(--text-primary);
  transition: box-shadow 0.25s ease;
}

body.typing-pulse {
  box-shadow: inset 0 0 0 2px rgba(118, 247, 255, 0.25), inset 0 0 24px rgba(255, 158, 217, 0.12);
}

.card {
  background: linear-gradient(120deg, rgba(118, 247, 255, 0.08), rgba(255, 158, 217, 0.08)), rgba(12, 12, 20, 0.92);
  border: 1px solid var(--border);
  box-shadow: 0 22px 44px rgba(0, 0, 0, 0.46), 0 0 1px rgba(118, 247, 255, 0.4);
  position: relative;
  overflow: hidden;
}

.card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0 16%, var(--trace) 18% 20%, transparent 22% 36%, var(--trace) 38% 40%, transparent 42% 58%, var(--trace) 60% 62%, transparent 64%);
  background-size: 220% 220%;
  animation: traceFlow 12s linear infinite;
  pointer-events: none;
}

.card::after {
  content: '';
  position: absolute;
  inset: 8%;
  border: 1px solid rgba(118, 247, 255, 0.15);
  border-radius: 10px;
  pointer-events: none;
}

.card-title {
  text-transform: uppercase;
  letter-spacing: 1.5px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 12px rgba(118, 247, 255, 0.4));
}

.button {
  background: linear-gradient(130deg, rgba(118, 247, 255, 0.15), rgba(255, 158, 217, 0.18));
  border: 1px solid rgba(118, 247, 255, 0.5);
  color: var(--text-primary);
  transition: transform 0.2s ease, box-shadow 0.2s;
}

.button:hover {
  transform: translateY(-1px) scale(1.02);
  box-shadow: 0 16px 26px rgba(118, 247, 255, 0.35);
}

@keyframes traceFlow {
  0% { background-position: 0% 0%; opacity: 0.9; }
  50% { background-position: 50% 50%; opacity: 1; }
  100% { background-position: 100% 100%; opacity: 0.9; }
}
